//! Independent fixtures are generated by tools/operator_fixtures.py on the benchmark workstation.
use crate::{kernels::device, model::sha};
use cuda_core::{CudaContext, DeviceBuffer, simt::LaunchConfig};
use serde_json::Value;
use std::{fs, path::PathBuf};

fn cfg(items: usize) -> LaunchConfig {
    LaunchConfig {
        grid_dim: (items.div_ceil(128) as u32, 1, 1),
        block_dim: (128, 1, 1),
        shared_mem_bytes: 0,
    }
}
fn rows(n: usize, threads: u32) -> LaunchConfig {
    LaunchConfig {
        grid_dim: (n as u32, 1, 1),
        block_dim: (threads, 1, 1),
        shared_mem_bytes: 0,
    }
}
/// Decode appends sixteen L2-prefetch blocks to attention and O quantization.
fn prefetching(mut config: LaunchConfig) -> LaunchConfig {
    config.grid_dim.0 += 16;
    config
}
/// Prefetch hints target this allocation; outputs must not change.
const HINT: u32 = 1 << 20;

#[test]
fn independent_operators() -> anyhow::Result<()> {
    let root = PathBuf::from(
        std::env::var("CLEAN_OPERATOR_FIXTURES")
            .expect("set CLEAN_OPERATOR_FIXTURES to the independent fixture directory"),
    );
    let manifest: Value = serde_json::from_slice(&fs::read(root.join("manifest.json"))?)?;
    let context = CudaContext::new(0)?;
    let stream = context.default_stream();
    let module = device::load(&context)?;
    let hint = DeviceBuffer::<i8>::zeroed(&stream, HINT as usize)?;
    let hint_cache = DeviceBuffer::<u16>::zeroed(&stream, 4096 * 1024)?;
    for case in manifest["cases"].as_array().unwrap() {
        let op = case["op"].as_str().unwrap();
        let bytes = |key: &str| -> anyhow::Result<Vec<u8>> {
            let meta = &case["tensors"][key];
            let data = fs::read(root.join(meta["file"].as_str().unwrap()))?;
            anyhow::ensure!(
                sha(&data) == meta["sha256"].as_str().unwrap(),
                "fixture hash: {key}"
            );
            Ok(data)
        };
        let f32s = |key: &str| -> anyhow::Result<Vec<f32>> {
            Ok(bytes(key)?
                .chunks_exact(4)
                .map(|b| f32::from_le_bytes(b.try_into().unwrap()))
                .collect())
        };
        let f = |key: &str| -> anyhow::Result<DeviceBuffer<f32>> {
            Ok(DeviceBuffer::from_host(&stream, &f32s(key)?)?)
        };
        let b = |key: &str| -> anyhow::Result<DeviceBuffer<u16>> {
            let values: Vec<_> = bytes(key)?
                .chunks_exact(2)
                .map(|b| u16::from_le_bytes(b.try_into().unwrap()))
                .collect();
            Ok(DeviceBuffer::from_host(&stream, &values)?)
        };
        let i8s = |key: &str| -> anyhow::Result<DeviceBuffer<i8>> {
            let values: Vec<_> = bytes(key)?.into_iter().map(|x| x as i8).collect();
            Ok(DeviceBuffer::from_host(&stream, &values)?)
        };
        let width = case["width"].as_u64().unwrap_or(0) as usize;
        let position = case["position"].as_u64().unwrap_or(0) as u32;
        let position_buffer = DeviceBuffer::from_host(&stream, &[0_u32, position])?;
        if op == "quantize" {
            let x = f("x")?;
            let mut q = DeviceBuffer::<i8>::zeroed(&stream, x.len())?;
            let mut scale = DeviceBuffer::<f32>::zeroed(&stream, x.len() / width)?;
            // SAFETY: generated complete rows, block width matches kernel's shared array.
            unsafe {
                module.quantize(
                    &stream,
                    rows(scale.len(), 1024),
                    &x,
                    width as u32,
                    &mut q,
                    &mut scale,
                    &hint,
                    0,
                    0,
                )?;
            }
            assert_eq!(
                q.to_host_vec(&stream)?
                    .into_iter()
                    .map(|x| x as u8)
                    .collect::<Vec<_>>(),
                bytes("q")?,
                "{}",
                case["name"]
            );
            assert_eq!(
                scale.to_host_vec(&stream)?,
                f32s("scale")?,
                "{}",
                case["name"]
            );
            let mut prefetched_q = DeviceBuffer::<i8>::zeroed(&stream, x.len())?;
            let mut prefetched_scale = DeviceBuffer::<f32>::zeroed(&stream, scale.len())?;
            // SAFETY: as above; appended blocks only issue in-bounds L2 hints.
            unsafe {
                module.quantize(
                    &stream,
                    prefetching(rows(scale.len(), 1024)),
                    &x,
                    width as u32,
                    &mut prefetched_q,
                    &mut prefetched_scale,
                    &hint,
                    0,
                    HINT,
                )?;
            }
            assert_eq!(prefetched_q.to_host_vec(&stream)?, q.to_host_vec(&stream)?);
            assert_eq!(
                prefetched_scale.to_host_vec(&stream)?,
                scale.to_host_vec(&stream)?
            );
            let maximum: Vec<_> = f32s("x")?
                .chunks_exact(width)
                .map(|row| row.iter().fold(1e-8_f32, |m, v| m.max(v.abs())).to_bits())
                .collect();
            let maximum = DeviceBuffer::from_host(&stream, &maximum)?;
            unsafe {
                module.quantize_with_max(
                    &stream,
                    cfg(x.len()),
                    &x,
                    width as u32,
                    &maximum,
                    &mut q,
                    &mut scale,
                )?;
            }
            assert_eq!(
                q.to_host_vec(&stream)?
                    .into_iter()
                    .map(|v| v as u8)
                    .collect::<Vec<_>>(),
                bytes("q")?
            );
            assert_eq!(scale.to_host_vec(&stream)?, f32s("scale")?);
            continue;
        }
        let expected = f32s("out")?;
        let mut out = DeviceBuffer::<f32>::zeroed(&stream, expected.len())?;
        // SAFETY: each independent fixture declares full, validated fixed-model shapes.
        // Buffers remain alive until each branch synchronizes, and outputs do not alias inputs.
        unsafe {
            match op {
                "norm" => {
                    let x = f("x")?;
                    let g = f("gain")?;
                    module.norm(&stream, rows(out.len() / width, 256), &x, &g, &mut out)?;
                    stream.synchronize()?;
                    if width == 4096 {
                        let plain = out.to_host_vec(&stream)?;
                        let mut quant = DeviceBuffer::<i8>::zeroed(&stream, out.len())?;
                        let mut scale = DeviceBuffer::<f32>::zeroed(&stream, out.len() / width)?;
                        module.quantize(
                            &stream,
                            rows(scale.len(), 1024),
                            &out,
                            width as u32,
                            &mut quant,
                            &mut scale,
                            &hint,
                            0,
                            0,
                        )?;
                        let plain_q = quant.to_host_vec(&stream)?;
                        let plain_scale = scale.to_host_vec(&stream)?;
                        let mut maxima = DeviceBuffer::<u32>::zeroed(&stream, scale.len())?;
                        module.norm_quantize(
                            &stream,
                            rows(scale.len(), 1024),
                            &x,
                            &g,
                            &mut out,
                            &mut quant,
                            &mut scale,
                            &mut maxima,
                        )?;
                        assert_eq!(out.to_host_vec(&stream)?, plain, "fused norm output");
                        assert_eq!(quant.to_host_vec(&stream)?, plain_q, "fused norm INT8");
                        assert_eq!(
                            scale.to_host_vec(&stream)?,
                            plain_scale,
                            "fused norm scales"
                        );
                    }
                }
                "linear" => {
                    let q = i8s("q")?;
                    let a = f("asc")?;
                    let w = i8s("w")?;
                    let s = f("ws")?;
                    module.linear(
                        &stream,
                        cfg(out.len() * 32),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(out.to_host_vec(&stream)?, expected, "DP4A {}", case["name"]);
                    let residual = DeviceBuffer::from_host(
                        &stream,
                        &(0..out.len())
                            .map(|i| ((i % 17) as f32 - 8.0) * 0.0625)
                            .collect::<Vec<_>>(),
                    )?;
                    let mut plain_residual = DeviceBuffer::<f32>::zeroed(&stream, out.len())?;
                    module.residual(
                        &stream,
                        cfg(out.len()),
                        &residual,
                        &out,
                        &mut plain_residual,
                    )?;
                    let mut combined = DeviceBuffer::<f32>::zeroed(&stream, out.len())?;
                    module.linear_residual(
                        &stream,
                        cfg(out.len() * 32),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &residual,
                        &mut out,
                        &mut combined,
                        width as u32,
                    )?;
                    assert_eq!(out.to_host_vec(&stream)?, expected, "fused projection");
                    assert_eq!(
                        combined
                            .to_host_vec(&stream)?
                            .into_iter()
                            .map(f32::to_bits)
                            .collect::<Vec<_>>(),
                        plain_residual
                            .to_host_vec(&stream)?
                            .into_iter()
                            .map(f32::to_bits)
                            .collect::<Vec<_>>(),
                        "fused residual bits"
                    );
                    let mut second = DeviceBuffer::<f32>::zeroed(&stream, out.len())?;
                    let mut third = DeviceBuffer::<f32>::zeroed(&stream, out.len())?;
                    module.linear_pair(
                        &stream,
                        cfg(out.len() * 2 * 32),
                        &q,
                        &a,
                        width as u32,
                        &w,
                        &s,
                        &mut out,
                        &w,
                        &s,
                        &mut second,
                    )?;
                    assert_eq!(out.to_host_vec(&stream)?, expected, "pair first");
                    assert_eq!(second.to_host_vec(&stream)?, expected, "pair second");
                    module.linear_triple(
                        &stream,
                        cfg(out.len() * 3 * 32),
                        &q,
                        &a,
                        width as u32,
                        &w,
                        &s,
                        &mut out,
                        &w,
                        &s,
                        &mut second,
                        &w,
                        &s,
                        &mut third,
                        &hint_cache,
                        &hint_cache,
                        &position_buffer,
                        width as u32,
                    )?;
                    assert_eq!(out.to_host_vec(&stream)?, expected, "triple first");
                    assert_eq!(second.to_host_vec(&stream)?, expected, "triple second");
                    assert_eq!(third.to_host_vec(&stream)?, expected, "triple third");
                    module.linear_prefill(
                        &stream,
                        cfg(a.len().div_ceil(16) * s.len().div_ceil(8) * 32),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(out.to_host_vec(&stream)?, expected, "MMA {}", case["name"]);
                    module.linear_splitk(
                        &stream,
                        rows(a.len().div_ceil(16) * s.len().div_ceil(8), 256),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(
                        out.to_host_vec(&stream)?,
                        expected,
                        "split-K {}",
                        case["name"]
                    );
                    module.linear_tiled(
                        &stream,
                        rows(a.len().div_ceil(32) * s.len().div_ceil(64), 256),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(
                        out.to_host_vec(&stream)?,
                        expected,
                        "tiled MMA {}",
                        case["name"]
                    );
                    let amap = crate::tensor::map(&stream, &q, a.len(), width, 64)?;
                    let bmap = crate::tensor::map(&stream, &w, s.len(), width, 128)?;
                    module.linear_large(
                        &stream,
                        rows(a.len().div_ceil(64) * s.len().div_ceil(128), 256),
                        &amap,
                        &a,
                        &bmap,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                }
                "rope" => {
                    let x = f("x")?;
                    let t = f("table")?;
                    module.rope(
                        &stream,
                        cfg(out.len() / 2),
                        &x,
                        &t,
                        32,
                        &position_buffer,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    let gain = DeviceBuffer::from_host(
                        &stream,
                        &(0..128)
                            .map(|i| (i as f32 % 13.0 - 6.0) * 0.25)
                            .collect::<Vec<_>>(),
                    )?;
                    let mut normed = DeviceBuffer::<f32>::zeroed(&stream, x.len())?;
                    let mut plain = DeviceBuffer::<f32>::zeroed(&stream, x.len())?;
                    module.norm(&stream, rows(x.len() / 128, 256), &x, &gain, &mut normed)?;
                    module.rope(
                        &stream,
                        cfg(x.len() / 2),
                        &normed,
                        &t,
                        32,
                        &position_buffer,
                        &mut plain,
                    )?;
                    let mut fused = DeviceBuffer::from_host(&stream, &f32s("x")?)?;
                    module.norm_rope(
                        &stream,
                        rows(x.len() / 128, 128),
                        &mut fused,
                        &gain,
                        &t,
                        32,
                        &position_buffer,
                    )?;
                    assert_eq!(
                        fused.to_host_vec(&stream)?,
                        plain.to_host_vec(&stream)?,
                        "fused head norm/RoPE"
                    );
                    let nr = x.len() / 4096;
                    let raw_k = f32s("x")?[..nr * 1024].to_vec();
                    let k = DeviceBuffer::from_host(&stream, &raw_k)?;
                    let v = DeviceBuffer::from_host(&stream, &raw_k)?;
                    let mut normalized_k = DeviceBuffer::<f32>::zeroed(&stream, k.len())?;
                    let mut rotated_k = DeviceBuffer::<f32>::zeroed(&stream, k.len())?;
                    module.norm(
                        &stream,
                        rows(k.len() / 128, 256),
                        &k,
                        &gain,
                        &mut normalized_k,
                    )?;
                    module.rope(
                        &stream,
                        cfg(k.len() / 2),
                        &normalized_k,
                        &t,
                        8,
                        &position_buffer,
                        &mut rotated_k,
                    )?;
                    let mut reference_ck = DeviceBuffer::<u16>::zeroed(&stream, 4096 * 1024)?;
                    let mut reference_cv = DeviceBuffer::<u16>::zeroed(&stream, 4096 * 1024)?;
                    module.cache(
                        &stream,
                        cfg(k.len()),
                        &rotated_k,
                        &v,
                        &position_buffer,
                        &mut reference_ck,
                        &mut reference_cv,
                    )?;
                    let mut fused_q = DeviceBuffer::from_host(&stream, &f32s("x")?)?;
                    let mut fused_k = DeviceBuffer::from_host(&stream, &raw_k)?;
                    let mut ck = DeviceBuffer::<u16>::zeroed(&stream, 4096 * 1024)?;
                    let mut cv = DeviceBuffer::<u16>::zeroed(&stream, 4096 * 1024)?;
                    module.prepare_qk(
                        &stream,
                        rows(nr * 40, 128),
                        &mut fused_q,
                        &mut fused_k,
                        &v,
                        &gain,
                        &gain,
                        &t,
                        &position_buffer,
                        &mut ck,
                        &mut cv,
                    )?;
                    assert_eq!(
                        fused_q.to_host_vec(&stream)?,
                        plain.to_host_vec(&stream)?,
                        "prepared Q"
                    );
                    assert_eq!(
                        fused_k.to_host_vec(&stream)?,
                        rotated_k.to_host_vec(&stream)?,
                        "prepared K"
                    );
                    assert_eq!(
                        ck.to_host_vec(&stream)?,
                        reference_ck.to_host_vec(&stream)?,
                        "prepared K cache"
                    );
                    assert_eq!(
                        cv.to_host_vec(&stream)?,
                        reference_cv.to_host_vec(&stream)?,
                        "prepared V cache"
                    );
                }
                "attention" => {
                    let q = f("q")?;
                    // Fixtures describe logical [token, head, coordinate] keys.
                    // Pack those same values into the runtime's coordinate-major cache.
                    let raw_k: Vec<_> = bytes("k")?
                        .chunks_exact(2)
                        .map(|b| u16::from_le_bytes(b.try_into().unwrap()))
                        .collect();
                    let mut transposed = vec![0_u16; 4096 * 1024];
                    for (i, value) in raw_k.iter().enumerate() {
                        transposed[i % 1024 * 4096 + i / 1024] = *value;
                    }
                    let k = DeviceBuffer::from_host(&stream, &transposed)?;
                    let mut values = vec![0_u16; 4096 * 1024];
                    for (i, bytes) in bytes("v")?.chunks_exact(2).enumerate() {
                        values[i] = u16::from_le_bytes(bytes.try_into().unwrap());
                    }
                    let v = DeviceBuffer::from_host(&stream, &values)?;
                    module.attention(
                        &stream,
                        rows(out.len() / 128, 128),
                        &q,
                        &k,
                        &v,
                        &position_buffer,
                        &mut out,
                        &hint,
                        0,
                        0,
                    )?;
                    stream.synchronize()?;
                    let unsplit = out.to_host_vec(&stream)?;
                    let mut prefetched = DeviceBuffer::<f32>::zeroed(&stream, out.len())?;
                    module.attention(
                        &stream,
                        prefetching(rows(out.len() / 128, 128)),
                        &q,
                        &k,
                        &v,
                        &position_buffer,
                        &mut prefetched,
                        &hint,
                        0,
                        HINT,
                    )?;
                    assert_eq!(
                        prefetched.to_host_vec(&stream)?,
                        unsplit,
                        "prefetching attention"
                    );
                    if position as usize + out.len() / 4096 <= 512 {
                        module.attention_prefill(
                            &stream,
                            rows(out.len() / 512, 512),
                            &q,
                            &k,
                            &v,
                            &position_buffer,
                            &mut out,
                        )?;
                        stream.synchronize()?;
                        assert_eq!(
                            out.to_host_vec(&stream)?,
                            unsplit,
                            "four-head prefill attention"
                        );
                    }

                    let mut scores = DeviceBuffer::<f32>::zeroed(&stream, out.len() / 128 * 4096)?;
                    let tiles = (position as usize + out.len() / 4096).div_ceil(64);
                    module.attention_scores(
                        &stream,
                        rows(out.len() / 128 * tiles, 128),
                        &q,
                        &k,
                        &position_buffer,
                        tiles as u32,
                        &mut scores,
                    )?;
                    module.attention_finish(
                        &stream,
                        rows(out.len() / 128, 128),
                        &scores,
                        &v,
                        &position_buffer,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(out.to_host_vec(&stream)?, unsplit, "split attention");
                    // Exercise the decode launch shape, including prefetch blocks.
                    module.attention_softmax(
                        &stream,
                        prefetching(rows(out.len() / 128, 128)),
                        &mut scores,
                        &position_buffer,
                        &hint,
                        0,
                        HINT,
                    )?;
                    module.attention_values(
                        &stream,
                        rows(out.len() / 32, 32),
                        &scores,
                        &v,
                        &position_buffer,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(out.to_host_vec(&stream)?, unsplit, "split PV attention");
                }
                "swiglu" => {
                    let g = f("gate")?;
                    let u = f("up")?;
                    let mut maxima = DeviceBuffer::from_host(&stream, &[1e-8_f32.to_bits()])?;
                    module.swiglu(&stream, cfg(out.len()), &g, &u, &mut out, &mut maxima)?;
                    stream.synchronize()?;
                    let maximum = out
                        .to_host_vec(&stream)?
                        .iter()
                        .fold(1e-8_f32, |m, v| m.max(v.abs()));
                    assert_eq!(
                        maxima.to_host_vec(&stream)?[0],
                        maximum.to_bits(),
                        "SwiGLU maximum"
                    );
                }
                "residual" => {
                    let a = f("a")?;
                    let b = f("b")?;
                    module.residual(&stream, cfg(out.len()), &a, &b, &mut out)?;
                    stream.synchronize()?;
                }
                "head" => {
                    let x = f("x")?;
                    let w = b("w")?;
                    module.head(&stream, cfg(out.len() * 32), &x, &w, &mut out)?;
                    stream.synchronize()?;
                    let original: Vec<_> = out
                        .to_host_vec(&stream)?
                        .into_iter()
                        .map(f32::to_bits)
                        .collect();
                    let packed = crate::packing::PackedBf16::new(&w.to_host_vec(&stream)?);
                    let words = DeviceBuffer::from_host(&stream, &packed.words)?;
                    let offsets = DeviceBuffer::from_host(&stream, &packed.offsets)?;
                    let exceptions = DeviceBuffer::from_host(&stream, &packed.exceptions)?;
                    module.head_packed(
                        &stream,
                        cfg(out.len() * 32),
                        &x,
                        &words,
                        &offsets,
                        &exceptions,
                        &mut out,
                        6144,
                    )?;
                    assert_eq!(
                        out.to_host_vec(&stream)?
                            .into_iter()
                            .map(f32::to_bits)
                            .collect::<Vec<_>>(),
                        original,
                        "packed head exact bits"
                    );
                }
                "embedding" => {
                    let ids: Vec<_> = bytes("ids")?
                        .chunks_exact(4)
                        .map(|b| u32::from_le_bytes(b.try_into().unwrap()))
                        .collect();
                    let ids = DeviceBuffer::from_host(&stream, &ids)?;
                    let w = b("w")?;
                    module.embedding(&stream, cfg(out.len()), &ids, &w, &mut out)?;
                    stream.synchronize()?;
                }
                _ => anyhow::bail!("unknown operator {op}"),
            }
        }
        let got = out.to_host_vec(&stream)?;
        let exact = matches!(op, "linear" | "embedding" | "residual" | "rope");
        let mut error = 0_f64;
        let mut energy = 0_f64;
        for (i, (&a, &b)) in got.iter().zip(&expected).enumerate() {
            assert!(
                a.is_finite() && (a - b).abs() <= if exact { 0.0 } else { 2e-4 + 0.01 * b.abs() },
                "{} element {i}: {a} vs {b}",
                case["name"]
            );
            error += (a as f64 - b as f64).powi(2);
            energy += (b as f64).powi(2);
        }
        assert!(
            (error / energy.max(1e-20)).sqrt() <= 0.005,
            "{} relative L2",
            case["name"]
        );
    }
    Ok(())
}

#[test]
fn gpu_argmax_ties_and_rejection() -> anyhow::Result<()> {
    let ctx = CudaContext::new(0)?;
    let stream = ctx.default_stream();
    let module = device::load(&ctx)?;
    let mut cases = vec![
        vec![0.0, -0.0],
        vec![-0.0, 0.0],
        vec![f32::MIN],
        vec![f32::NAN],
        vec![0.0, f32::INFINITY],
        vec![f32::NEG_INFINITY, 0.0],
    ];
    for n in [31, 32, 33, 1023, 1024, 1025, crate::VOCAB] {
        let mut x: Vec<_> = (0..n).map(|i| (i % 97) as f32).collect();
        x[n - 1] = f32::MAX;
        cases.push(x.clone());
        x[7] = f32::MAX;
        cases.push(x);
    }
    for x in cases {
        let input = DeviceBuffer::from_host(&stream, &x)?;
        let mut output = DeviceBuffer::<u32>::zeroed(&stream, 1)?;
        // SAFETY: exact 1024-thread CTA and one result slot; all inputs admitted by this reduction.
        unsafe {
            module.select_token(&stream, rows(1, 1024), &input, &mut output)?;
        }
        let actual = output.to_host_vec(&stream)?[0];
        assert_eq!(actual, crate::model::argmax(&x).unwrap_or(u32::MAX));
    }
    Ok(())
}

#[test]
fn packed_bf16_exhaustive_gpu() -> anyhow::Result<()> {
    let input: Vec<u16> = (0..131072)
        .map(|i| (i as u16).wrapping_mul(40503))
        .collect();
    let packed = crate::packing::PackedBf16::new(&input);
    let context = CudaContext::new(0)?;
    let stream = context.default_stream();
    let module = device::load(&context)?;
    let words = DeviceBuffer::from_host(&stream, &packed.words)?;
    let offsets = DeviceBuffer::from_host(&stream, &packed.offsets)?;
    let exceptions = DeviceBuffer::from_host(&stream, &packed.exceptions)?;
    let mut out = DeviceBuffer::<u16>::zeroed(&stream, input.len())?;
    // SAFETY: the private packer produces the complete matching bitstream; every
    // exceptional code points within its own chunk's at-most-256-entry table.
    unsafe {
        module.unpack_head(
            &stream,
            cfg(out.len()),
            &words,
            &offsets,
            &exceptions,
            &mut out,
        )?;
    }
    assert_eq!(out.to_host_vec(&stream)?, input);
    Ok(())
}

#[test]
fn fused_gate_up_matches_separate() -> anyhow::Result<()> {
    let ctx = CudaContext::new(0)?;
    let stream = ctx.default_stream();
    let module = device::load(&ctx)?;
    for (k, n) in [(128_usize, 33_usize), (4096, 12288)] {
        let q = DeviceBuffer::from_host(
            &stream,
            &(0..k)
                .map(|i| ((i * 13 % 255) as i32 - 127) as i8)
                .collect::<Vec<_>>(),
        )?;
        let w0 = DeviceBuffer::from_host(
            &stream,
            &(0..k * n)
                .map(|i| ((i * 31 % 255) as i32 - 127) as i8)
                .collect::<Vec<_>>(),
        )?;
        let w1 = DeviceBuffer::from_host(
            &stream,
            &(0..k * n)
                .map(|i| ((i * 17 % 251) as i32 - 125) as i8)
                .collect::<Vec<_>>(),
        )?;
        let asc = DeviceBuffer::from_host(&stream, &[0.002_f32])?;
        let s0 = DeviceBuffer::from_host(
            &stream,
            &(0..n)
                .map(|i| 0.0001 * ((i % 7 + 1) as f32))
                .collect::<Vec<_>>(),
        )?;
        let s1 = DeviceBuffer::from_host(
            &stream,
            &(0..n)
                .map(|i| 0.0001 * ((i % 11 + 1) as f32))
                .collect::<Vec<_>>(),
        )?;
        let mut g = DeviceBuffer::<f32>::zeroed(&stream, n)?;
        let mut u = DeviceBuffer::<f32>::zeroed(&stream, n)?;
        let mut act = DeviceBuffer::<f32>::zeroed(&stream, n)?;
        let mut maximum = DeviceBuffer::from_host(&stream, &[1e-8_f32.to_bits()])?;
        // SAFETY: complete aligned rows; separate read-only matrices and outputs.
        unsafe {
            module.linear_pair(
                &stream,
                cfg(n * 64),
                &q,
                &asc,
                k as u32,
                &w0,
                &s0,
                &mut g,
                &w1,
                &s1,
                &mut u,
            )?;
            module.swiglu(&stream, cfg(n), &g, &u, &mut act, &mut maximum)?;
        }
        let bits = |x: Vec<f32>| x.into_iter().map(f32::to_bits).collect::<Vec<_>>();
        let expected_g = bits(g.to_host_vec(&stream)?);
        let expected_u = bits(u.to_host_vec(&stream)?);
        let values = act.to_host_vec(&stream)?;
        let expected_max = values.iter().fold(1e-8_f32, |m, v| m.max(v.abs()));
        let expected_act = bits(values);
        maximum.copy_from_host(&stream, &[1e-8_f32.to_bits()])?;
        // SAFETY: exactly eight full warps per CTA, one admitted activation row.
        unsafe {
            module.linear_swiglu(
                &stream,
                rows(n.div_ceil(8), 256),
                &q,
                &asc,
                k as u32,
                &w0,
                &s0,
                &mut g,
                &w1,
                &s1,
                &mut u,
                &mut act,
                &mut maximum,
                4096,
            )?;
        }
        assert_eq!(bits(g.to_host_vec(&stream)?), expected_g, "gate bits");
        assert_eq!(bits(u.to_host_vec(&stream)?), expected_u, "up bits");
        assert_eq!(
            bits(act.to_host_vec(&stream)?),
            expected_act,
            "activation bits"
        );
        assert_eq!(
            maximum.to_host_vec(&stream)?[0],
            expected_max.to_bits(),
            "activation maximum"
        );
    }
    Ok(())
}

#[test]
fn integer_rounding_boundaries() -> anyhow::Result<()> {
    let mut input: Vec<_> = (0..=u16::MAX)
        .map(|x| f32::from_bits(u32::from(x) << 16))
        .collect();
    input.extend((-131072..=131072).map(|x| x as f32 / 1024.0));
    for i in -127..127 {
        let tie = i as f32 + 0.5;
        for bits in [tie.to_bits() - 1, tie.to_bits(), tie.to_bits() + 1] {
            input.push(f32::from_bits(bits));
        }
    }
    input.extend((0..1_000_000_u32).map(|x| f32::from_bits(x.wrapping_mul(2654435761))));
    let expected: Vec<_> = input
        .iter()
        .map(|&x| f64::from(x).clamp(-127.0, 127.0).round_ties_even() as i8)
        .collect();
    let ctx = CudaContext::new(0)?;
    let stream = ctx.default_stream();
    let module = device::load(&ctx)?;
    let device_input = DeviceBuffer::from_host(&stream, &input)?;
    let mut out = DeviceBuffer::<i8>::zeroed(&stream, input.len())?;
    unsafe {
        module.rounding_probe(&stream, cfg(input.len()), &device_input, &mut out)?;
    }
    let actual = out.to_host_vec(&stream)?;
    for (i, (&a, &e)) in actual.iter().zip(&expected).enumerate() {
        assert_eq!(a, e, "input bits {:08x}", input[i].to_bits());
    }
    Ok(())
}
